#!/bin/bash
set -e
PID=$(pgrep -f 'node.*server\.js' | head -1)
DATABASE_URL=$(cat /proc/$PID/environ | tr '\0' '\n' | grep '^DATABASE_URL=' | cut -d= -f2-)
JWT_SECRET=$(cat /proc/$PID/environ | tr '\0' '\n' | grep '^JWT_SECRET=' | cut -d= -f2-)
echo "JWT_SECRET found: ${#JWT_SECRET} chars"
echo "DB: $DATABASE_URL" | sed 's/:[^:@]*@/:***@/'

# Generate token using node jsonwebtoken
node << 'EONODE'
const jwt = require('/var/app/current/node_modules/jsonwebtoken');
const {Client} = require('/var/app/current/node_modules/pg');
const {v4:uuidv4} = require('/var/app/current/node_modules/uuid');
const {execSync} = require('child_process');
const pid = require('child_process').execSync("pgrep -f 'node.*server\.js' | head -1").toString().trim();
const env = require('fs').readFileSync('/proc/'+pid+'/environ','utf8');
const vars = Object.fromEntries(env.split(String.fromCharCode(0)).filter(Boolean).map(e=>{const i=e.indexOf('=');return[e.slice(0,i),e.slice(i+1)];}));
const JWT_SECRET = vars.JWT_SECRET;
(async()=>{
  const db = new Client({connectionString:vars.DATABASE_URL,ssl:{rejectUnauthorized:false}});
  await db.connect();
  const {rows} = await db.query("SELECT u->>'id' AS id, u->>'role' AS role, u->>'teamId' AS teamid FROM app_state s, jsonb_array_elements(s.data->'users') u WHERE u->>'email'='medico.teste@vitras.com.br'");
  await db.end();
  const u=rows[0];
  const tok = jwt.sign({jti:uuidv4(),sessionId:uuidv4(),id:u.id,name:'Medico Test',role:u.role,email:'medico.teste@vitras.com.br',teamId:u.teamid,teamName:'',unitId:'unit-default',municipalityId:'',capabilities:{},impersonation:null,breakGlass:null},JWT_SECRET,{algorithm:'HS256',issuer:'vitras-backend',audience:'vitras-client',expiresIn:'2h'});
  require('fs').writeFileSync('/tmp/tok.txt', tok);
  console.log('Token written, length:', tok.length);
})().catch(e=>{console.error(e.message);process.exit(1);});
EONODE

echo '{"name":"FC10 Test","cpf":"","cns":"","dataNascimento":"1990-01-01","sexo":"M","phone":"(11) 99999-9999","address":"Rua Teste 100 Centro Test SP","microArea":"A"}' > /tmp/body.json

echo "=== POST /patients verbose ==="
HTTP_CODE=$(curl -v --max-time 10 -o /tmp/resp.json -w '%{http_code}' \
  -X POST \
  -H "Authorization: Bearer $(cat /tmp/tok.txt)" \
  -H 'Content-Type: application/json' \
  -d @/tmp/body.json \
  http://localhost:8080/patients 2>&1)
echo "EXIT: $?"
echo "HTTP_CODE raw output: '$HTTP_CODE'"
echo "Response body:"
cat /tmp/resp.json 2>/dev/null || echo "(empty)"
rm -f /tmp/tok.txt /tmp/body.json /tmp/resp.json
